INSERT INTO oshi_skills (oshi_card_id, skill_type, skill_name, description, holopower_cost, effect_json) VALUES ('HBP06-007', 'NORMAL', 'PONじゃないもん！！', '[ターンに1回]相手のターンで、自分の〈ロボ子さん〉がダウンした時に使える：自分のデッキの上から2枚をアーカイブする。その後、自分のアーカイブの〈ロボ子さん〉1枚を手札に戻す。', 2, '{"type": "UNIMPLEMENTED", "rawText": "[ターンに1回]相手のターンで、自分の〈ロボ子さん〉がダウンした時に使える：自分のデッキの上から2枚をアーカイブする。その後、自分のアーカイブの〈ロボ子さん〉1枚を手札に戻す。"}'::jsonb);
INSERT INTO oshi_skills (oshi_card_id, skill_type, skill_name, description, holopower_cost, effect_json) VALUES ('HBP06-007', 'SP', 'ボクの『高性能っぷり』を堪能してよね♡', '[ゲームに1回]自分のデッキを2枚引いた後、手札2枚をアーカイブする。その後、自分のアーカイブの〈ろぼさー〉を好きな枚数選び、自分の〈ロボ子さん〉に割り振って付けられる。', 1, '{"type": "UNIMPLEMENTED", "rawText": "[ゲームに1回]自分のデッキを2枚引いた後、手札2枚をアーカイブする。その後、自分のアーカイブの〈ろぼさー〉を好きな枚数選び、自分の〈ロボ子さん〉に割り振って付けられる。"}'::jsonb);
