INSERT INTO member_arts (member_card_id, name, description, cost_cheer_json, effect_json, order_index) VALUES ('HBP06-055', '二人で紡いだ魔法 100+赤+50', '自分のデッキの上から4枚を公開する。公開したホロメン1枚につき、このアーツ+20。そして公開したカードをアーカイブする。その中にイベントがあるなら、自分のデッキを2枚引く。', '{"BLUE": 1, "PURPLE": 1}'::jsonb, '{"type": "UNIMPLEMENTED", "rawHeader": "青紫二人で紡いだ魔法 100+赤+50", "rawEffect": "自分のデッキの上から4枚を公開する。公開したホロメン1枚につき、このアーツ+20。そして公開したカードをアーカイブする。その中にイベントがあるなら、自分のデッキを2枚引く。"}'::jsonb, 0);
